// ── PDF print — replicates exact WORK-LIFE Autorización de Trabajo layout ────
// ── Pre-process logos: render at 2x for crispness ───────────────────────────
// White background removal done via CSS mix-blend-mode:multiply so fine text
// like BORGWARNER is never erased by flood-fill.
async function processLogosForPdf(orden, views, pins) {
  const result = {};
  const promises = [];
  views.forEach(v => {
    (pins[v.id]||[]).forEach(pin => {
      const pos = orden.posiciones[pin.key];
      if (!pos || !pos.logoImg) return;
      if (result[pos.logoImg] !== undefined) return;
      result[pos.logoImg] = null;
      const p = new Promise(resolve => {
        const img = new window.Image();
        img.onload = () => {
          const sz = 160; // resolución de origen fija; el tamaño visible se controla por % (logoPct)
          const r  = img.naturalWidth / img.naturalHeight;
          // Render at 2x for sharpness; display dimensions are half that
          const cw = r >= 1 ? sz * 2 : Math.round(sz * r * 2);
          const ch = r >= 1 ? Math.round(sz / r * 2) : sz * 2;
          const c  = document.createElement('canvas');
          c.width = cw; c.height = ch;
          const ctx = c.getContext('2d');
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, cw, ch);
          result[pos.logoImg] = {
            dataUrl: c.toDataURL('image/png'),
            w: Math.round(cw / 2),
            h: Math.round(ch / 2)
          };
          resolve();
        };
        img.onerror = () => { result[pos.logoImg] = { dataUrl: pos.logoImg, w: 160, h: 160 }; resolve(); };
        img.src = pos.logoImg;
      });
      promises.push(p);
    });
  });
  await Promise.all(promises);
  return result;
}

