function PdfModal({ html, onClose, titulo = "Autorización de Trabajo", archivo = "OrdenBordado.html" }) {
  if (!html) return null;

  const handleDownload = () => {
    const blob = new Blob([html], { type: "text/html;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "OrdenBordado.html";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
  };

  return (
    <div style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,.85)",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-start",padding:"16px"}}>
      <div style={{width:"100%",maxWidth:900,height:"calc(100vh - 32px)",background:"#fff",borderRadius:12,overflow:"hidden",display:"flex",flexDirection:"column"}}>
        {/* Toolbar */}
        <div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 16px",borderBottom:"1px solid #ddd",background:"#f5f5f5",flexShrink:0}}>
          <div style={{flex:1,fontWeight:700,color:"#111",fontSize:13}}>Vista previa — Autorización de Trabajo</div>
          <button onClick={handleDownload}
            style={{background:"#1a7a4a",color:"#fff",border:"none",borderRadius:7,padding:"6px 14px",fontSize:12,fontWeight:700,cursor:"pointer"}}>
            ⬇ Descargar para imprimir
          </button>
          <button onClick={onClose}
            style={{background:"#c0392b",color:"#fff",border:"none",borderRadius:7,padding:"6px 12px",fontSize:12,fontWeight:700,cursor:"pointer"}}>
            ✕ Cerrar
          </button>
        </div>
        {/* srcDoc iframe — CSS completamente aislado, imágenes base64 sin restricciones */}
        <iframe
          srcDoc={html}
          style={{flex:1,width:"100%",border:"none",background:"#fff"}}
          title="Autorización de Trabajo"
          sandbox="allow-same-origin"
        />
        {/* Footer */}
        <div style={{padding:"7px 16px",borderTop:"1px solid #ddd",fontSize:11,color:"#555",background:"#f9f9f9",flexShrink:0}}>
          💡 Descarga → abre en Chrome/Edge → <b>Ctrl+P</b> (⌘+P en Mac) → <b>Guardar como PDF</b>
        </div>
      </div>
    </div>
  );
}

