    if (!nuevo) return { ok: false, msg: "El nombre no puede estar vacío." };
    const viejo = (logo.nombre || "").trim();
    if (nuevo === viejo) return { ok: false, msg: "Es el mismo nombre." };
    const viejoSlug = logo.id || logoSlug(viejo);
